static void sdb_fini(Sdb* s, int donull) {
        if (!s) {
                return;
        }
        sdb_hook_free (s);
        cdb_free (&s->db);
        if (s->lock) {
                sdb_unlock (sdb_lock_file (s->dir));
        }
        sdb_ns_free (s);
        s->refs = 0;
        free (s->name);
        free (s->path);
        ls_free (s->ns);
        sdb_ht_free (s->ht);
        sdb_journal_close (s);
        if (s->fd != -1) {
                close (s->fd);
                s->fd = -1;
        }
        free (s->ndump);
        free (s->dir);
        free (sdbkv_value (&s->tmpkv));
        s->tmpkv.base.value_len = 0;
        if (donull) {
                memset (s, 0, sizeof (Sdb));
        }
}

